package com.gameaggregator.publisherservice.domain; import jakarta.persistence.*; import java.time.LocalDate; import java.util.UUID; @Entity @Table(name="distribution_rights") public class DistributionRight{@Id public UUID id=UUID.randomUUID();@Column(nullable=false)public UUID publisherId;@Column(nullable=false)public UUID gameId;@Column(nullable=false)public String territory;@Column(nullable=false)public LocalDate startsOn;public LocalDate endsOn;protected DistributionRight(){}public DistributionRight(UUID p,UUID g,String t,LocalDate s,LocalDate e){publisherId=p;gameId=g;territory=t;startsOn=s;endsOn=e;}}
